// ItemTable.get("ITEM_POTION") or ItemTable.get(13)   (a bare "POTION" / "potion" works too)
Object.defineProperty(ItemTable, 'get', { enumerable: false, value(id) {
  if (typeof id === 'number') { for (const k in this) if (this[k].id === id) return this[k]; return null; }
  const s = String(id).toUpperCase().replace(/[^A-Z0-9]+/g, '_'); return this[s] || this['ITEM_' + s] || null;
} });
window.ItemTable = ItemTable;
